import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_positions"].copy()
    events = inputs["position_events"].copy()

    # 1. Distinct by batch_seq (same event delivered more than once -> apply once)
    events = events.drop_duplicates(subset=["batch_seq"], keep="first")

    # Build target lookup per key (dtype-safe via itertuples)
    target_state = {}
    for row in target.itertuples(index=False):
        key = (row.account_id, row.symbol)
        target_state[key] = {
            "qty": row.qty,
            "price": row.price,
            "row_version": row.row_version,
        }

    # 2. Replay guard - vectorized via left merge against target's row_version
    if len(events):
        tgt_versions = target[["account_id", "symbol", "row_version"]].rename(
            columns={"row_version": "_target_row_version"}
        )
        events = events.merge(tgt_versions, on=["account_id", "symbol"], how="left")
        keep_mask = events["_target_row_version"].isna() | (
            events["row_version"] > events["_target_row_version"]
        )
        events = events[keep_mask].drop(columns=["_target_row_version"])

    # 3. Order by row_version, batch_seq (stable sort; keys are unique so this is deterministic)
    events = events.sort_values(
        by=["account_id", "symbol", "row_version", "batch_seq"], kind="mergesort"
    )

    state = dict(target_state)
    last_effect = {}  # key -> (removed_bool, row_version)

    for row in events.itertuples(index=False):
        key = (row.account_id, row.symbol)
        current = state.get(key)
        op = row.op
        qty = row.qty
        price = row.price
        version = row.row_version

        removed = False

        if op == "D":
            if current is not None:
                current = None
                removed = True
            # missing row -> no-op, current stays None, removed stays False
        elif op in ("I", "U"):
            is_zero = (not pd.isna(qty)) and (qty == 0)
            if is_zero:
                if current is not None:
                    current = None
                    removed = True
                # missing row -> no-op
            else:
                if current is not None and op == "U" and pd.isna(price):
                    new_price = current["price"]
                else:
                    new_price = None if pd.isna(price) else price
                current = {"qty": qty, "price": new_price, "row_version": version}
                removed = False
        # unknown op -> treated as no-op (not expected per schema)

        state[key] = current
        last_effect[key] = (removed, version)

    # Build new_positions
    rows = []
    for key, val in state.items():
        if val is not None:
            qty_val = val["qty"]
            try:
                qty_out = int(qty_val)
            except (ValueError, TypeError):
                qty_out = qty_val
            rows.append(
                {
                    "account_id": key[0],
                    "symbol": key[1],
                    "qty": qty_out,
                    "price": val["price"],
                    "row_version": val["row_version"],
                }
            )

    new_positions = pd.DataFrame(
        rows, columns=["account_id", "symbol", "qty", "price", "row_version"]
    )

    if len(new_positions):
        new_positions = new_positions.sort_values(
            by=["account_id", "symbol"], kind="mergesort"
        ).reset_index(drop=True)
        new_positions["account_id"] = new_positions["account_id"].astype("int64")
        new_positions["qty"] = new_positions["qty"].astype("int64")
        new_positions["row_version"] = new_positions["row_version"].astype("int64")
        new_positions["price"] = new_positions["price"].astype("float64")
    else:
        new_positions = pd.DataFrame(
            {
                "account_id": pd.Series(dtype="int64"),
                "symbol": pd.Series(dtype="object"),
                "qty": pd.Series(dtype="int64"),
                "price": pd.Series(dtype="float64"),
                "row_version": pd.Series(dtype="int64"),
            }
        )

    # Build closed_positions: one row per key whose LAST applied event actually
    # removed an existing row (an event that did nothing does not count).
    closed_rows = []
    for key, (removed, version) in last_effect.items():
        if removed:
            closed_rows.append(
                {
                    "account_id": key[0],
                    "symbol": key[1],
                    "closed_version": version,
                }
            )

    closed_positions = pd.DataFrame(
        closed_rows, columns=["account_id", "symbol", "closed_version"]
    )

    if len(closed_positions):
        closed_positions = closed_positions.sort_values(
            by=["account_id", "symbol"], kind="mergesort"
        ).reset_index(drop=True)
        closed_positions["account_id"] = closed_positions["account_id"].astype("int64")
        closed_positions["closed_version"] = closed_positions["closed_version"].astype(
            "int64"
        )
    else:
        closed_positions = pd.DataFrame(
            {
                "account_id": pd.Series(dtype="int64"),
                "symbol": pd.Series(dtype="object"),
                "closed_version": pd.Series(dtype="int64"),
            }
        )

    return {"new_positions": new_positions, "closed_positions": closed_positions}
